static const float sustain = .98 - 2*q14-q30, change = q14, ds = q10, tic8 = 1.0/255, ffac = q17;

float aTan2(float y, float x) {float angle;	 float abs_y = abs(y);
if (x >= 0) {float r = (x - abs_y) / (x + abs_y); angle = 1-r;} 
else {float r = (x + abs_y) / (abs_y - x); angle = 3-r; }	
angle = angle * M_PI/4.0;
return y < 0 ? -angle : angle;}

float2 fstep2 (float2 xy) {return 1.0/res*round(res*xy);}

float GetDist(float2 uvi) {float2 tmp; tmp = (tex2D (sampler_pc_main, uvi).gb); 
return 1.0078125-tmp.y -0.015625*tmp.x;} // = 1-(tmp.y + 1.0/res2*(tmp.x-.50));}

float2 PutDist(float x) {float tmp; tmp = fstep2(1-x);
  return (float2(res2*((1-x)-tmp)+.495,tmp));}

float tdist (float d) {return d + pow(d,5);}

float MinDist (float2 uvi) 
{  float tmp; float4 nb; float4 nb2; float2 pix;
   pix = texsize.zw*(1.0+max(abs(uvi.x-.5),abs(uvi.y-.5))*2.00);   
   nb.x = GetDist(uvi+pix*float2(-1,-1));   nb.y = GetDist(uvi+pix*float2(1,-1));
   nb.z = GetDist(uvi+pix*float2(1,1));     nb.w = GetDist(uvi+pix*float2(-1,1));         
   nb2.x = GetDist(uvi+pix*float2(0,-1));   nb2.y = GetDist(uvi+pix*float2(1,0));          
   nb2.z = GetDist(uvi+pix*float2(0,1));    nb2.w = GetDist(uvi+pix*float2(-1,0));
   //Eo.S. more efficient usage of min to get min value of all 8 GetDist calls, removes 11ALU
   nb = min( nb, nb2 );
   nb.xy = min( nb.xy, nb.zw );
   return min( nb.x, nb.y );}

float3 Get1 (float2 uvi) {float diff;
  diff = abs (GetPixel(uvi).r- GetBlur1(uvi).r);
  return lerp (GetPixel(uvi), GetBlur1(uvi),0.2*diff);} 

float2 mbox (float3 uvi) {float3 zz, zz0, zzlo; float tmp, ang1, len;
  uvi = (frac(uvi/8.0+.5)-.5)*8.0;  ang1 = aTan2(uvi.x,uvi.y); len = dot(uvi.xy,uvi.xy)/5;
  zz = float3 (len, ang1, uvi.z);
  zz0 = lerp(uvi,zz,q19)+q8;
  for (int n = 0; n <= 7; n++) {
    zz = 2.0*clamp(zz,-1,1)-zz;  tmp = dot(zz,zz);
    zz *= clamp(max(.25/tmp, .25), 0.0, 1.0)*4;
    zz = ffac*zz + zz0; if (n == 5) {zzlo = zz;}}
return float2(length(zzlo), length(zz));}

shader_body {uv0 = uv_orig;
uv1 = (uv0-.5)*aspect.xy*tele;
uv = (uv-.5)*(1-(1*ds/(GetDist(uv0))+dot(compxy,uv1))) + .5;
float3 noise = frac(9.3453*tex2D (sampler_noise_lq,uv*4+rand_frame.yz)); 
float3 noiseBiased = noise - 0.5;  //Eo.S. combine the subtraction on noise to a single float3 
bool seed = (noise.g < .2);
if (!seed) 
{  dist = MinDist(uv)  +  0.008 * (noiseBiased.x) * abs(noiseBiased.y);}    
   else {dist = noise.r;}
 dist = min(dist,GetDist(uv)) - (ds+.3*tele*dot(compxy,uv1))*(1-dist)*.8 ;

limit = 12 + 8 * dist;
uv2 = mul(float3(uv1*tdist(dist),tdist(dist))/myzoom,RotMat)+CamPos;
float2 box = mbox(uv2);
len = lerp(box.x,box.y,saturate(2-2*dist));
struc = len/limit/2+.3;

float2 shlen = (uv1-1);
float2 uv3 =  (uv - shlen * (.06 ));
struc *= 1- ( GetDist(uv)-.5*length(uv-uv3)>GetDist(uv3))*.5*(1-dist);
float sus = sustain; if (seed) {sus = 1;}

float3 inside  = float3 (lerp(struc,Get1(uv).r,sus), PutDist(dist)); //##?
float3 outside = Get1(uv)*sus-tic8;
ret = lerp (inside,outside,saturate(.005/change*(len-limit)));
}

